package com.kennedy.wallet.controller;
import com.kennedy.wallet.service.AuthService;import com.kennedy.wallet.domain.User;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.responses.ApiResponse;import io.swagger.v3.oas.annotations.responses.ApiResponses;import io.swagger.v3.oas.annotations.tags.Tag;
@RestController @RequestMapping("/api/auth") @Tag(name="Authentication") public class AuthController {private final AuthService auth;public AuthController(AuthService a){auth=a;}
 @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) @Operation(summary="Register a wallet user") @ApiResponses({@ApiResponse(responseCode="201",description="User and wallet created"),@ApiResponse(responseCode="400",description="Invalid phone, password, or already registered phone")}) public Object register(@Valid @RequestBody Credentials c){User u=auth.register(c.phone(),c.password());return new UserView(u.getId().toString(),u.getPhone());}
 @PostMapping("/login") @Operation(summary="Authenticate and issue access and refresh tokens") @ApiResponses({@ApiResponse(responseCode="200",description="Token pair issued"),@ApiResponse(responseCode="400",description="Invalid credentials or locked account"),@ApiResponse(responseCode="429",description="Authentication rate limit exceeded")}) public AuthService.TokenPair login(@Valid @RequestBody Credentials c){return auth.login(c.phone(),c.password());}
 @PostMapping("/refresh") @Operation(summary="Rotate a refresh token") @ApiResponses({@ApiResponse(responseCode="200",description="Rotated token pair"),@ApiResponse(responseCode="400",description="Refresh token is invalid, expired, or reused")}) public AuthService.TokenPair refresh(@Valid @RequestBody RefreshRequest r){return auth.refresh(r.refreshToken());}
 @PostMapping("/logout") @ResponseStatus(HttpStatus.NO_CONTENT) @Operation(summary="Revoke a refresh token") @ApiResponses({@ApiResponse(responseCode="204",description="Token revoked"),@ApiResponse(responseCode="400",description="Invalid request")}) public void logout(@Valid @RequestBody RefreshRequest r){auth.logout(r.refreshToken());}
 public record Credentials(@NotBlank String phone,@NotBlank @Size(min=8,max=72) String password){} public record RefreshRequest(@NotBlank String refreshToken){} public record UserView(String id,String phone){}
}
